describe('Notification Visual Distinction', () => {
    beforeEach(() => {
        cy.visit('/notifications');
    });

    it('should display unread notifications with a bold font', () => {
        cy.get('.notification').each(($notification) => {
            const isRead = $notification.hasClass('read');
            if (!isRead) {
                expect($notification).to.have.css('font-weight', 'bold');
            }
        });
    });

    it('should display read notifications with normal font weight', () => {
        cy.get('.notification').each(($notification) => {
            const isRead = $notification.hasClass('read');
            if (isRead) {
                expect($notification).to.have.css('font-weight', 'normal');
            }
        });
    });
});
